/** Actual inactive saved hosts, observer publication order, channels and complete-process restart. */
@EventBusSubscriber(modid="vandorlabs")
public final class TrapdoorHostChecks {
    private static final BlockPos BASE=new BlockPos(3204,80,3204),FAILED=BASE.south(4),DIAGONAL=BASE.south(8),COLD=new BlockPos(3232,80,3232);private static int checks;private static boolean watch;private static Housing[] blocks=new Housing[2];private static BlockEntityType<Probe>[] types=new BlockEntityType[2];
    private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}private static boolean enabled(){return phase().startsWith("trapdoor-host-");}private static void need(boolean value,String message){checks++;if(!value)throw new AssertionError("Trapdoor host: "+message);}
    private static final class Housing extends NativeTrapdoorBlock {final int index;Housing(int index){super(BlockBehaviour.Properties.of().strength(2.5F).noOcclusion().dynamicShape(),index==1);this.index=index;}protected BlockEntityType<?> entityType(){return types[index];}protected MapCodec<? extends BaseEntityBlock> codec(){return MapCodec.unit(this);}}
    public static final class Probe extends NativeTrapdoorEntity {Probe(BlockEntityType<?> type,BlockPos pos,BlockState state){super(type,pos,state);}@Override public void setChanged(){if(watch){var first=at(getLevel(),BASE);var second=at(getLevel(),BASE.east());need(first.settings().choices().position==2&&second.settings().choices().position==2&&first.trapdoorVisual().settings().choices().position==2&&second.trapdoorVisual().settings().choices().position==2,"every setting/visual installs before dirty observer");}super.setChanged();}}
    @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;event.register(Registries.BLOCK,h->{for(int i=0;i<2;i++){blocks[i]=new Housing(i);h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","trapdoor_host_fixture_"+i),blocks[i]);}});event.register(Registries.BLOCK_ENTITY_TYPE,h->{for(int i=0;i<2;i++){final int index=i;types[i]=BlockEntityType.Builder.of((pos,state)->new Probe(types[index],pos,state),blocks[i]).build(null);h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","trapdoor_host_fixture_"+i),types[i]);}});}}
    private static NativeTrapdoorEntity tile(ServerLevel level,BlockPos pos){return NativeTrapdoorEntity.at(level,pos);}
    private static CompoundTag old(BlockPos pos,BlockPos mate,boolean diagonal){var tag=new CompoundTag();tag.putInt("housingTexture",NativeTrapdoorSettings.defaultTexture());tag.putInt("TrapdoorTrigger",1);tag.putIntArray("RedstoneChannels",new int[]{17});if(mate!=null)tag.putLong("TrapdoorPartner",NativeTrapdoorLinks.releasedPosition(mate));tag.putInt("DiagonalFacing",2);tag.putInt("DiagonalGroupFacing",2);var caps=new CompoundTag();caps.putString("Owner","opaque:trapdoor-world");tag.put("ForgeCaps",caps);tag.putString("FutureTrapdoorData","preserve:original");return tag;}
    private static NativeTrapdoorEntity put(ServerLevel level,BlockPos pos,int family,CompoundTag tag){level.getChunkAt(pos);level.setBlock(pos,blocks[family].defaultBlockState().setValue(NativeTrapdoorBlock.FACING,Direction.NORTH),18);var tile=tile(level,pos);tile.loadWithComponents(tag,level.registryAccess());tile.onLoad();return tile;}
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {boolean denied;Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("63a0f4b6-3270-43b4-9b93-cce9ba42ecda"),"TrapdoorHost"));}public boolean mayUseItemAt(BlockPos pos,Direction side,net.minecraft.world.item.ItemStack held){return !(denied&&pos.equals(BASE.east()))&&super.mayUseItemAt(pos,side,held);}}
    private static void scalars(ServerLevel level)throws Exception{
        long began=System.nanoTime();var rows=JsonParser.parseString(Files.readString(Path.of(System.getProperty("vandorlabs.trapdoorLifecycleReference")))).getAsJsonArray();List<BlockPos> previous=new ArrayList<>();int profiles=0;var delta=BASE.subtract(new BlockPos(15,80,8));
        for(var element:rows){var row=element.getAsJsonObject();if(row.get("fault").getAsInt()==3)continue;for(var at:previous)level.setBlock(at,Blocks.AIR.defaultBlockState(),18);previous.clear();NativeTrapdoorEntity owner=null;int index=0;for(var raw:row.getAsJsonArray("input")){var tag=TagParser.parseTag(raw.getAsString());var at=new BlockPos(tag.getInt("x"),tag.getInt("y"),tag.getInt("z")).offset(delta);boolean diagonal=row.get("diagonal").getAsBoolean()^(row.get("fault").getAsInt()==9&&index>0);for(String key:new String[]{"TrapdoorPartner","TrapdoorSquare"})if(tag.contains(key,Tag.TAG_LONG))tag.putLong(key,NativeTrapdoorLinks.releasedPosition(NativeTrapdoorLinks.releasedPosition(tag.getLong(key)).offset(delta)));var members=tag.getList("TrapdoorAssembly",Tag.TAG_LONG);for(int i=0;i<members.size();i++)members.set(i,LongTag.valueOf(NativeTrapdoorLinks.releasedPosition(NativeTrapdoorLinks.releasedPosition(((LongTag)members.get(i)).getAsLong()).offset(delta))));level.getChunkAt(at);level.setBlock(at,blocks[diagonal?1:0].defaultBlockState().setValue(NativeTrapdoorBlock.FACING,Direction.from2DDataValue(row.get("facing").getAsInt())),18);var tile=(NativeTrapdoorEntity)level.getBlockEntity(at);tile.loadWithComponents(tag,level.registryAccess());previous.add(at);if(index++==0)owner=tile;}
            owner.tickServer();var expected=row.getAsJsonObject("repaired");if(expected.has("resolutionFailure")){need(owner.inert(),"invalid mixed diagonal snapshot remains recoverably inert");continue;}need(!owner.inert()&&owner.trapdoorVisual()!=null,"source-resolvable world host profile="+profiles+" family="+row.get("diagonal")+" position="+row.get("position")+" facing="+row.get("facing")+" relation="+row.get("relation")+" fault="+row.get("fault")+" trigger="+row.get("trigger")+" power="+row.get("power")+" failure="+owner.failureReason());var pose=owner.trapdoorVisual().pose();need(pose.hinge==expected.get("hinge").getAsDouble()&&pose.travel==expected.get("travel").getAsDouble()&&pose.overhang==expected.get("overhang").getAsDouble(),"actual host hinge/travel/cover source profile="+profiles+" row="+row.get("relation")+"/"+row.get("fault"));if(row.get("diagonal").getAsBoolean())need(pose.reverse==expected.get("reverse").getAsBoolean()&&pose.closedReverse==expected.get("closedReverse").getAsBoolean()&&pose.lift==expected.get("lift").getAsInt(),"actual host diagonal resolved source profile="+profiles);profiles++;
        }for(var at:previous)level.setBlock(at,Blocks.AIR.defaultBlockState(),18);need(profiles==8568,"actual resolved profile coverage");long elapsed=(System.nanoTime()-began)/1000000;need(elapsed<90000,"actual-host collision publication must remain bounded elapsedMs="+elapsed);System.out.println("[vandorlabs][trapdoor-host] scalars PASS profiles="+profiles+" elapsedMs="+elapsed+" loaded source roles; cold membership separately frozen");
    }
    private static int coldRegionMask(ServerLevel level){int mask=0;for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)if(NativeTrapdoorEntity.loaded(level,COLD.offset(dx*16,0,dz*16)))mask|=1<<((dx+1)*3+dz+1);return mask;}
    private static void cold(ServerLevel level){var owner=put(level,COLD,0,old(COLD,COLD.west(),false));need(!NativeTrapdoorEntity.loaded(level,COLD.west())&&!NativeTrapdoorEntity.loaded(level,COLD.north()),"cold link faces start unavailable");int chunks=level.getChunkSource().getLoadedChunksCount(),beforeMask=coldRegionMask(level);owner.tickServer();need(owner.group().size()==1&&owner.links().partner().equals(COLD.west()),"cold partner falls back locally without deleting saved relation");var actor=new Actor(level);actor.setPos(COLD.getX()+.5,COLD.getY(),COLD.getZ()+.5);var before=owner.settings();var choice=before.choices();var next=new NativeTrapdoorSettings(new TrapdoorData(choice.texture,2,choice.rawLayout,0,choice.tileTexture,choice.cover,choice.sliding,choice.intoWall,choice.overSurface),before.channels(),before.facing(),before.hingeSide(),before.rotationFlipped(),false);need(owner.configure(actor,next),"source cold fallback configures only loaded owner");int afterMask=coldRegionMask(level);need((afterMask&~beforeMask)==0&&!NativeTrapdoorEntity.loaded(level,COLD.west())&&!NativeTrapdoorEntity.loaded(level,COLD.north()),"deferred repair/power/configuration do not force cold links or physical inputs regionMask="+beforeMask+"->"+afterMask+" west="+NativeTrapdoorEntity.loaded(level,COLD.west())+" north="+NativeTrapdoorEntity.loaded(level,COLD.north())+" globalChunks="+chunks+"->"+level.getChunkSource().getLoadedChunksCount());}
    private static void fallback(ServerLevel level){var pos=DIAGONAL.south(3);level.getChunkAt(pos);for(boolean inert:new boolean[]{false,true}){var state=blocks[1].defaultBlockState().setValue(NativeTrapdoorBlock.OPEN,true);level.setBlock(pos,state,18);if(inert){var tag=old(pos,null,true);tag.putInt("NativeTrapdoorLinks",2);((NativeTrapdoorEntity)level.getBlockEntity(pos)).loadWithComponents(tag,level.registryAccess());}else level.removeBlockEntity(pos);long began=System.nanoTime();var shape=state.getCollisionShape(level,pos);need(!shape.isEmpty(),"open diagonal missing/inert fallback has local collision");var bounds=shape.bounds();need(bounds.minX>=0&&bounds.minY>=0&&bounds.minZ>=0&&bounds.maxX<=1&&bounds.maxY<=1&&bounds.maxZ<=1,"fallback collision stays clipped to own cell");for(int query=0;query<64;query++)need(state.getCollisionShape(level,pos)==shape,"missing/inert endpoint queries reuse bounded shape");need((System.nanoTime()-began)/1000000<5000,"fallback collision publication must avoid repeated optimize/decompose");level.setBlock(pos,Blocks.AIR.defaultBlockState(),18);}System.out.println("[vandorlabs][trapdoor-host] fallback PASS missing/inert open diagonal bounded reuse");}
    private static void write(ServerLevel level){
        var first=put(level,BASE,0,old(BASE,BASE.east(),false));var second=put(level,BASE.east(),0,old(BASE.east(),BASE,false));need(first.group().size()==2&&second.group().size()==2,"actual old-packed reciprocal pair");first.tickServer();second.tickServer();need(!first.open()&&!second.open(),"source positive trigger settles closed");
        level.setBlock(BASE.east().south(),Blocks.REDSTONE_BLOCK.defaultBlockState(),3);first.scheduleRefresh();first.tickServer();need(first.open()&&second.open(),"follower physical input opens both actual block states");level.setBlock(BASE.east().south(),Blocks.AIR.defaultBlockState(),3);first.scheduleRefresh();first.tickServer();need(!first.open()&&!second.open(),"physical loss closes both");
        var actor=new Actor(level);actor.setPos(BASE.getX()+.5,BASE.getY(),BASE.getZ()+.5);actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);var before=first.settings();var choices=new TrapdoorData(before.choices().texture,2,2,0,false,false,true,false,true);var next=new NativeTrapdoorSettings(choices,ChannelList.of(5,9),before.facing(),0,false,false);actor.denied=true;need(!first.configure(actor,next)&&first.settings()==before,"denied follower refuses all-member configuration");actor.denied=false;watch=true;try{need(first.configure(actor,next),"authorized group configuration");}finally{watch=false;}need(first.settings().channels().equals(ChannelList.of(5,9))&&second.settings().channels().equals(ChannelList.of(5,9))&&level.getBlockState(BASE).getValue(NativeTrapdoorBlock.HALF)==Half.TOP&&level.getBlockState(BASE.east()).getValue(NativeTrapdoorBlock.HALF)==Half.TOP,"choices/channels/metadata apply to pair");
        TrapdoorMenuChecks.run(first,actor,next);
        var client=new NativeTrapdoorEntity(types[0],BASE,first.getBlockState());var update=first.getUpdateTag(level.registryAccess());need(!update.toString().contains("opaque:")&&!update.contains("TrapdoorPartner")&&!update.contains("TrapdoorAssembly"),"public projection excludes opaque/world relations");client.loadWithComponents(update,level.registryAccess());need(client.canOffsetClosedLeaf()==first.canOffsetClosedLeaf()&&!client.canOffsetClosedLeaf(),"paired public eligibility matches server without private links");need(client.trapdoorVisual().pose().equals(first.trapdoorVisual().pose())&&client.trapdoorVisual().artwork().equals(first.trapdoorVisual().artwork()),"public client reconstructs resolved immutable projection without loaded neighbors");
        var failed=old(FAILED,null,false);failed.putInt("NativeTrapdoorLinks",2);level.getChunkAt(FAILED);level.setBlock(FAILED,blocks[0].defaultBlockState(),18);var inert=(NativeTrapdoorEntity)level.getBlockEntity(FAILED);inert.loadWithComponents(failed,level.registryAccess());need(inert.inert()&&!inert.requestOpen(actor,true)&&!inert.configure(actor,next),"future coordinate schema stays inert");var saved=inert.saveWithoutMetadata(level.registryAccess());need(saved.getInt("NativeTrapdoorLinks")==2&&saved.getCompound("ForgeCaps").equals(failed.getCompound("ForgeCaps"))&&saved.getString("FutureTrapdoorData").equals("preserve:original"),"failed load retains original opaque NBT");
        var diagonal=put(level,DIAGONAL,1,old(DIAGONAL,DIAGONAL.east(),true));var mate=put(level,DIAGONAL.east(),1,old(DIAGONAL.east(),DIAGONAL,true));diagonal.tickServer();mate.tickServer();actor.setPos(DIAGONAL.getX()+.5,DIAGONAL.getY(),DIAGONAL.getZ()+.5);var d=diagonal.settings();var band=new NativeTrapdoorSettings(new TrapdoorData(d.choices().texture,2,1,0,true,false,false,false,false),ChannelList.EMPTY,d.facing(),2,true,true);need(diagonal.configure(actor,band,true,null)&&diagonal.group().size()==1&&mate.group().size()==1&&diagonal.inverted()&&mate.inverted()&&diagonal.settings().hingeSide()==2&&mate.settings().hingeSide()==0,"diagonal band change unpairs all members and selected hinge stays local");
        level.removeBlock(BASE.east(),false);first.scheduleRefresh();first.tickServer();need(first.links().partner()==null&&first.group().size()==1,"loaded missing partner repairs before publication");level.setChunkForced(BASE.getX()>>4,BASE.getZ()>>4,true);System.out.println("[vandorlabs][trapdoor-host] behavior PASS oldpacked/physicalpower/auth/stagedprojection/DTO/inert/diagonalband/repair");
    }
    private static void read(ServerLevel level){level.getChunkAt(BASE);var first=tile(level,BASE);need(first!=null&&first.links().partner()==null&&first.geometryPosition()==2&&first.sliding()&&first.settings().channels().equals(ChannelList.of(5,9)),"separate process restores repaired/configured owner");var saved=first.saveWithoutMetadata(level.registryAccess());need(saved.getInt("NativeTrapdoorLinks")==1&&saved.getCompound("ForgeCaps").getString("Owner").equals("opaque:trapdoor-world"),"native coordinate marker/opaque caps survive restart");var failed=(NativeTrapdoorEntity)level.getBlockEntity(FAILED);need(failed!=null&&failed.inert()&&failed.saveWithoutMetadata(level.registryAccess()).getInt("NativeTrapdoorLinks")==2,"future snapshot stays inert after process restart");var diagonal=tile(level,DIAGONAL);need(diagonal!=null&&diagonal.inverted()&&diagonal.settings().hingeSide()==2&&diagonal.settings().rotationFlipped(),"diagonal metadata and selected rotation survive restart");}
    @SubscribeEvent public static void started(ServerStartedEvent event)throws Exception{if(!enabled())return;var level=event.getServer().overworld();if(phase().endsWith("write")){scalars(level);cold(level);fallback(level);TrapdoorTargetChecks.run(level,blocks[0],blocks[1]);write(level);}else read(level);event.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][trapdoor-host] "+(phase().endsWith("write")?"write":"read")+" PASS checks="+checks);event.getServer().halt(false);}
}
